import java.util.*;

class Solution {
    public List<Integer> commonValues(int[] a, int[] b) {
        HashSet<Integer> seen = new HashSet<>();
        for (int x : a) seen.add(x);
        HashSet<Integer> common = new HashSet<>();
        for (int x : b) {
            if (seen.contains(x)) common.add(x); // set keeps each value once
        }
        List<Integer> res = new ArrayList<>(common);
        Collections.sort(res); // increasing order
        return res;
    }
}

